import './frame.css';
import { boot } from '@seiza/web/bootstrap';
import fontUrl from '@seiza/web/fonts/IBMPlexSans-Regular.ttf?url';
// Generated by wasm-bindgen into web/pkg/ (gitignored); `just tycho dev` builds it.
import init, {
  back_to,
  command,
  complete,
  filter_line,
  copy,
  find,
  find_step,
  fit,
  open_file,
  open_row,
  open_sample,
  retry_engine,
  row,
  row_text,
  select,
  set_theme,
  start,
  toggle_perf,
} from '../pkg/tycho.js';
// The same asset wasm-bindgen would resolve; named here so the HTML preload and
// `init` fetch one URL (instantiateStreaming needs `application/wasm`).
import wasmUrl from '../pkg/tycho_bg.wasm?url';
import { createBridge } from '@seiza/duckdb/bridge';
// The sample, built by `just tycho data` (gitignored), emitted as a hashed
// asset; vite.config.ts checks it against data/MANIFEST.json. Fetched only
// when its row is pressed.
import sampleUrl from '../../data/gcat.parquet?url';
import { bindFrame, connectApp, focusFirstScreen, isDark, slotCanvas } from './frame/core.ts';
import { type Completion, frameSink, type RowValues } from './frame/state.ts';
// The page's other weights (the canvas draws Regular alone), the same
// release of Plex Sans as the UI face; fetched after the first frame.
import mediumUrl from './fonts/IBMPlexSans-Medium.woff2?url';
import semiBoldUrl from './fonts/IBMPlexSans-SemiBold.woff2?url';
// The command bar's and the log's face (`docs/DECISIONS.md`, "Scope",
// 2026-11-20): after the first frame too; the system's monospace until then.
import monoUrl from './fonts/IBMPlexMono-Regular.woff2?url';

// The prerendered frame works from now (`frame/core.ts`), and the canvas
// goes in the table's slot as GPUI adds it.
bindFrame();
slotCanvas(document.getElementById('table-slot')!);

const bridge = createBridge();
// `?bench`: the perf scripts query the same engine the app uses (row counts,
// paging experiments), and read the app's wasm memory to check the perf
// panel's. The bridge loads nothing until its first call.
const bench = new URLSearchParams(location.search).has('bench');
if (bench) (globalThis as { __tychoBridge?: typeof bridge }).__tychoBridge = bridge;

const instantiate = async () => {
  const exports = await init({ module_or_path: wasmUrl });
  if (bench) (globalThis as { __tychoWasmMemory?: WebAssembly.Memory }).__tychoWasmMemory = exports.memory;
  return exports;
};

void boot({
  init: instantiate,
  start: (font) => {
    // The page's text in the face the canvas draws, from the same bytes:
    // one download for both.
    document.fonts.add(new FontFace('IBM Plex Sans', font.slice()));
    start(font, bridge, sampleUrl, frameSink, isDark());
  },
  fontUrl,
  wasmUrl,
});

// React draws the frame's state from the first frame on: loaded after it,
// so first paint waits on none of it (`docs/DECISIONS.md`, "Scope",
// 2026-11-23, the page's framework).
const FIRST_FRAME = 'gpui:first-frame';
const painted = () => performance.getEntriesByName(FIRST_FRAME, 'mark').length > 0;
/** Medium and SemiBold, swapped in for the weights the browser synthesized
 *  from Regular until now, and Plex Mono: after the first frame, so first
 *  paint waits on none of them. */
function loadWeights(): void {
  for (const [family, url, weight] of [
    ['IBM Plex Sans', mediumUrl, '500'],
    ['IBM Plex Sans', semiBoldUrl, '600'],
    ['IBM Plex Mono', monoUrl, '400'],
  ] as const) {
    const face = new FontFace(family, `url(${url}) format('woff2')`, { weight, display: 'swap' });
    document.fonts.add(face);
    void face.load();
  }
}

const hydrate = () => {
  // What the page queued runs now, the wasm's calls bound since `start`.
  connectApp({
    open_file,
    open_sample,
    retry_engine,
    set_theme,
    toggle_perf,
    command,
    // Typed by the crate (`command::Completion`); wasm-bindgen says `any`.
    complete: (text, caret) => complete(text, caret) as Completion,
    filter_line: (column, op, values) => filter_line(column, op, values) ?? null,
    back_to,
    // Typed by the crate (`row::RowValues`).
    row: (index) => row(index) as Promise<RowValues | null>,
    fit,
    copy,
    row_text: (index, column) => row_text(index, column) as Promise<string | null>,
    select,
    open_row,
    find,
    find_step,
  });
  // GPUI took focus for its own input as its window opened.
  focusFirstScreen();
  loadWeights();
  void import('./frame/hydrate.tsx').then(({ hydrate }) => hydrate(document.getElementById('root')!));
};
// Looked for each animation frame: a PerformanceObserver's callback came
// as much as 0.7 s after the mark, and a press made before the first frame
// waits on it.
const watch = () => (painted() ? hydrate() : requestAnimationFrame(watch));
watch();
